.product-page01 {
  --product-page01-max-width: var(--container-max-width);
  --product-page01-gutter: var(--container-padding);
  --product-page01-gap: var(--section-content-gap);
  box-sizing: border-box;
  max-width: calc(var(--product-page01-max-width) + var(--product-page01-gutter) * 2);
  width: 100%;
  margin-inline: auto;
  padding: var(--card-padding) var(--product-page01-gutter) var(--space-10);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.product-page01 *, .product-page01 *::before, .product-page01 *::after { box-sizing: border-box; }
.product-page01 p, .product-page01 h1, .product-page01 h2, .product-page01 dl, .product-page01 dd { margin: 0; }
.product-page01-back { display: inline-flex; align-items: center; min-height: calc(var(--space-4) * 2.75); margin-block-end: var(--space-6); color: inherit; font-size: var(--typography-caption-size); font-weight: var(--font-weight-semibold); text-underline-offset: var(--space-1); }
.product-page01-back:focus-visible { outline: var(--focus-ring-width) solid var(--focus-ring-color); outline-offset: var(--focus-ring-offset); }
.product-page01 .product-page01-layout { gap: var(--product-page01-gap); }
.product-page01-gallery { flex: 1.15 1 0; min-width: 0; }
.product-page01 .product-page01-info { flex: 1 1 0; min-width: 0; padding-block-start: var(--space-4); gap: 0; }
.product-page01-eyebrow { font-size: var(--typography-micro-size); font-weight: var(--font-weight-semibold); letter-spacing: var(--letter-spacing-widest); line-height: var(--line-height-normal); overflow-wrap: anywhere; }
.product-page01 h1 { margin-block: var(--space-6); font-size: var(--typography-product-title-size); line-height: var(--line-height-tight); letter-spacing: var(--letter-spacing-tighter); font-weight: var(--font-weight-bold); overflow-wrap: anywhere; }
.product-page01 .product-page01-price { margin-block-start: var(--space-1); gap: var(--inline-gap-sm); flex-wrap: wrap; }
.product-page01-price > .text-muted { font-size: var(--typography-caption-size); }
.product-page01-description { margin-block: var(--space-8); font-size: var(--font-size-base); line-height: var(--line-height-relaxed); }
.product-page01 .product-page01-description { margin-block: var(--space-8); }
.product-page01-availability { width: 100%; }
.product-page01-availability h2 { font-size: var(--font-size-base); line-height: var(--line-height-normal); font-weight: var(--font-weight-semibold); margin-block-end: var(--space-3); }
.product-page01 .product-page01-stock-row { min-height: calc(var(--space-4) * 3); gap: var(--inline-gap); padding-block: var(--space-3); border-block-end: var(--border-width-thin) solid var(--border-default); }
.product-page01-stock-row dt { font-size: var(--typography-caption-size); font-weight: var(--font-weight-semibold); }
.product-page01-stock-row dd { font-size: var(--typography-caption-size); color: var(--text-muted); text-align: end; }
.product-page01 .product-page01-notice { margin-block-start: var(--space-4); font-size: var(--typography-caption-size); line-height: var(--line-height-relaxed); }
@media (max-width: 64rem) { .product-page01 { --product-page01-gap: calc(var(--space-4) * 2.5); } }
@media (max-width: 48rem) {
  .product-page01 { --product-page01-gutter: var(--space-4); }
  .product-page01 .product-page01-layout { flex-direction: column; gap: var(--inline-gap-lg); }
  .product-page01-gallery, .product-page01 .product-page01-info { width: 100%; flex-basis: auto; }
  .product-page01 .product-page01-info { padding-block-start: 0; }
  .product-page01 h1 { font-size: var(--typography-product-title-size); }
}

export interface ProductPage01Variant {
  size: string;
  stock: number;
}
export interface ProductPage01Product {
  name: string;
  amount: number;
  currency: string;
  locale: string;
  description: string;
  imageSrc?: string;
  imageAlt: string;
  variants: readonly ProductPage01Variant[];
}
export interface ProductPage01Props {
  as?: "main" | "section";
  product?: ProductPage01Product;
  backHref?: string;
  backLabel?: string;
  eyebrow?: string;
  priceNote?: string;
  availabilityHeading?: string;
  outOfStockLabel?: string;
  inStockLabel?: string;
  notice?: string;
}
export const sampleProduct: ProductPage01Product = {
  name: "Academy training jersey", amount: 28, currency: "GBP", locale: "en-GB",
  description: "Training wear. A concept for the academy collection, designed around life on and off the pitch. This is a fictional visual sample; designs, prices and availability are illustrative.",
  imageSrc: "/paraxe/product-page-01/jersey.svg", imageAlt: "Black academy training jersey with yellow collar and chest mark, front view",
  variants: [{ size: "XS", stock: 0 }, { size: "S", stock: 8 }, { size: "M", stock: 8 }, { size: "L", stock: 8 }, { size: "XL", stock: 8 }],
};
export function validateProductVariants(variants: readonly ProductPage01Variant[]): void {
  const sizes = new Set<string>();
  for (const variant of variants) {
    const size = variant.size.trim();
    if (!size || sizes.has(size) || !Number.isSafeInteger(variant.stock) || variant.stock < 0) throw new RangeError("Availability rows require unique size labels and non-negative integer stock.");
    sizes.add(size);
  }
}
